// Package generator writes a Go SDK package from a service's definitions, the
// way Pandora's generator-go-sdk writes go-azure-sdk: it reads nothing but the
// definitions, and every decision it makes about the API was already made by
// the importer.
//
// One package per server (BaseItemDto is everywhere, so per-tag packages would
// all import one another), laid out by tag in file names:
//
//	client.go                          Client and New
//	client_test.go                     the canned server the tests share
//	doc.go                             the package documentation
//	<tag>_method_<operation>.go        one per operation: the method, its
//	                                   <Name>Response, its
//	                                   <Name>Options, and for list
//	                                   operations a <Name>Complete pager
//	<tag>_method_<operation>_test.go   the operation's test (tests.go)
//	<tag>_model_<model>.go             one per model
//	<tag>_constants.go                 the tag's enums
//
// Requests go through a base client, named in Options.ClientImport:
// pandorest's own (the client package), which this package's tests build and
// run a generated package against, or one a repository keeps of its own, with
// what the README says generated code calls.
package generator

import (
	"bytes"
	"fmt"
	"go/format"
	"maps"
	"os"
	"path/filepath"
	"regexp"
	"slices"
	"strings"

	"github.com/katbyte/pandorest/definitions"
)

// Header starts every generated file but doc.go; Generated is how to tell a
// generated file from one written by hand.
const Header = "// Code generated by pandorest; DO NOT EDIT.\n"

// generatedRe matches the first line of a file pandorest generated, wherever
// the copy that wrote it lived: before it was a module of its own each
// repository carried one, and named it by its path (sdk/pandorest).
var generatedRe = regexp.MustCompile(`^// Code generated by ([\w.-]+/)*pandorest; DO NOT EDIT\.\n`)

// Generated reports whether src is a file pandorest generated, which is how a
// stale one is recognised for removal and a hand-written one beside it left
// alone: every generated file starts with the header but the package's
// doc.go, which starts by saying pandorest generated it.
func Generated(src []byte) bool { return generatedRe.Match(src) || docRe.Match(src) }

// docRe matches the first line of a generated package's doc.go, which says what wrote it in its package comment in place of the
// header: a linter skips a file marked generated and would miss the package comment (see docFile).
var docRe = regexp.MustCompile(`^// Package \w+ is a typed client for .*, generated by pandorest\n`)

// Options says where a service's package goes, where it came from and what
// it is built on.
type Options struct {
	// Dir is the package directory.
	Dir string
	// Definitions is the definitions directory, named in the package doc.
	Definitions string
	// Version is the version the document's file is named by, which the
	// package declares as DocumentVersion; empty declares none.
	Version string
	// ClientImport is the import path of the base client the package sends
	// its requests through.
	ClientImport string
	// Client, when set, is the source of client.go after its APIVersion
	// constant, in place of the default (see config.Service.Client).
	Client string
	// ClientService, when set, names the client.Service in the package
	// that the default client.go makes its client from.
	ClientService string
	// Credential and NewDoc word the default client.go's New in the
	// service's own way (see config.Service).
	Credential string
	NewDoc     string
	// Notes is a paragraph added to the package documentation.
	Notes string

	// Grouped lays the SDK out as packages (see config.Service.Grouped):
	// the types in Dir, a package per tag under it, and client. ImportPath
	// is then Dir's import path, which the packages import one another by,
	// and Packages names a tag's package where its lowercased name will not
	// do.
	Grouped    bool
	ImportPath string
	Packages   map[string]string

	// ClientPackage names the grouped layout's client package; empty is
	// client.
	ClientPackage string

	// InlineSingleOptions has an operation with one option take it as an
	// argument in place of the struct (see config.Service).
	InlineSingleOptions bool
}

// Generate writes the package and removes generated files it no longer
// produces. It returns the number of files written. A hand-written Go file
// where a generated one goes (a doc.go moved beside the types, say) is
// refused rather than overwritten.
func Generate(svc *definitions.Service, opts Options) (int, error) {
	files, err := Render(svc, opts)
	if err != nil {
		return 0, err
	}
	if err := os.MkdirAll(opts.Dir, 0o755); err != nil { //nolint:gosec // generated source, world-readable is right
		return 0, err
	}
	if err := removeStale(opts.Dir, files, opts.Grouped); err != nil {
		return 0, err
	}
	for _, name := range sortedKeys(files) {
		path := filepath.Join(opts.Dir, filepath.FromSlash(name))
		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil { //nolint:gosec // generated source, world-readable is right
			return 0, err
		}
		old, err := os.ReadFile(path) //nolint:gosec // a file in the package directory
		switch {
		case err == nil && bytes.Equal(old, files[name]):
			continue
		case err == nil && filepath.Ext(name) == ".go" && !Generated(old):
			return 0, fmt.Errorf("%s is written by hand, and generation would overwrite it: move it aside, or give it another name", path)
		}
		if err := os.WriteFile(path, files[name], 0o644); err != nil { //nolint:gosec // generated source, world-readable is right
			return 0, err
		}
	}

	return len(files), nil
}

// Render produces every file of the package, formatted, by name: a path
// under Dir with slashes, for the grouped layout.
func Render(svc *definitions.Service, opts Options) (map[string][]byte, error) {
	if err := definitions.Validate(svc); err != nil {
		return nil, err
	}
	g, err := newGen(svc, opts)
	if err != nil {
		return nil, err
	}

	sources := map[string]string{}
	add := func(name, src string) error {
		if _, ok := sources[name]; ok {
			return fmt.Errorf("two declarations would both be written to %s", name)
		}
		sources[name] = src
		return nil
	}
	if opts.Grouped {
		if err := g.renderGrouped(add); err != nil {
			return nil, err
		}

		return g.format(sources)
	}

	sources["client.go"] = g.clientFile()
	sources["client_test.go"] = g.testHelpersFile()
	sources["doc.go"] = g.docFile()
	sources["operations.go"] = g.operationsFile()
	if g.datesFile() {
		sources["time.go"] = g.timeFile()
	}
	if len(svc.IDs) > 0 {
		sources["ids.go"] = g.idsFile()
	}
	for gi := range svc.Groups {
		grp := &svc.Groups[gi]
		prefix := fileStem(grp.Name)
		if len(grp.Constants) > 0 {
			if err := add(prefix+"_constants.go", g.constantsFile(grp)); err != nil {
				return nil, err
			}
		}
		for mi := range grp.Models {
			m := &grp.Models[mi]
			if err := add(fileName(prefix, "model", m.Name), g.modelFile(m)); err != nil {
				return nil, err
			}
		}
		for oi := range grp.Operations {
			o := &grp.Operations[oi]
			name := fileName(prefix, "method", o.Name)
			if err := add(name, g.methodFile(o)); err != nil {
				return nil, err
			}
			if err := add(strings.TrimSuffix(name, ".go")+"_test.go", g.testFile(o)); err != nil {
				return nil, err
			}
		}
	}
	return g.format(sources)
}

// format checks the identifiers and gofmts every Go source; a file that is
// not Go (the groups map) goes as it is.
func (g *gen) format(sources map[string]string) (map[string][]byte, error) {
	if err := g.checkIdentifiers(); err != nil {
		return nil, err
	}

	files := make(map[string][]byte, len(sources))
	for name, src := range sources {
		if filepath.Ext(name) != ".go" {
			files[name] = []byte(src)

			continue
		}
		out, err := format.Source([]byte(src))
		if err != nil {
			return nil, fmt.Errorf("%s: generated code does not parse: %w\n%s", name, err, numbered(src))
		}
		files[name] = out
	}

	return files, nil
}

// removeStale deletes generated Go files, tests included, in dir that are not
// about to be written, and, for the grouped layout, in the packages under
// it, removing a package directory left empty. Hand-written files (no
// generated header) are left alone, wherever they are.
func removeStale(dir string, keep map[string][]byte, grouped bool) error {
	var dirs []string
	if err := filepath.WalkDir(dir, func(path string, e os.DirEntry, err error) error {
		if err != nil {
			return err
		}
		rel, err := filepath.Rel(dir, path)
		if err != nil {
			return err
		}
		switch {
		case e.IsDir() && path == dir:
			return nil
		case e.IsDir() && !grouped:
			return filepath.SkipDir
		case e.IsDir():
			dirs = append(dirs, path)

			return nil
		case filepath.Ext(e.Name()) != ".go" || keep[filepath.ToSlash(rel)] != nil:
			return nil
		}
		src, err := os.ReadFile(path) //nolint:gosec // a file in the package directory, which is the generator's to read and remove
		if err != nil {
			return err
		}
		if Generated(src) {
			return os.Remove(path) //nolint:gosec // a generated file in the package directory, which is the generator's to remove
		}

		return nil
	}); err != nil {
		return err
	}

	// deepest first, so a directory emptied by removing its subdirectory goes too
	slices.Reverse(dirs)
	for _, d := range dirs {
		if entries, err := os.ReadDir(d); err == nil && len(entries) == 0 {
			if err := os.Remove(d); err != nil {
				return err
			}
		}
	}

	return nil
}

// buildSuffixes are file name endings the go tool reads as build constraints
// (_test, and _<GOOS> or _<GOARCH> as the last element).
var buildSuffixes = func() map[string]bool {
	m := map[string]bool{}
	for s := range strings.FieldsSeq("test aix android darwin dragonfly freebsd hurd illumos ios js linux nacl netbsd openbsd plan9 solaris wasip1 windows zos " +
		"386 amd64 amd64p32 arm armbe arm64 arm64be loong64 mips mipsle mips64 mips64le mips64p32 mips64p32le ppc ppc64 ppc64le riscv riscv64 s390 s390x sparc sparc64 wasm") {
		m[s] = true
	}

	return m
}()

// fileStem lower-cases a name for use in a file name.
func fileStem(name string) string { return strings.ToLower(name) }

// fileName is <group>_<kind>_<name>.go, with the name kept from reading as a
// build constraint.
func fileName(prefix, kind, name string) string {
	return prefix + "_" + kindFile(kind, name)
}

// kindFile is <kind>_<name>.go, a file of the grouped layout, with the name
// kept from reading as a build constraint.
func kindFile(kind, name string) string {
	stem := fileStem(name)
	if buildSuffixes[stem] {
		stem += "type"
	}

	return kind + "_" + stem + ".go"
}

func sortedKeys[V any](m map[string]V) []string {
	return slices.Sorted(maps.Keys(m))
}

func numbered(src string) string {
	var b strings.Builder
	for i, line := range strings.Split(src, "\n") {
		fmt.Fprintf(&b, "%4d  %s\n", i+1, line)
	}

	return b.String()
}
